package com.primehr.rsp.evaluation;
import com.primehr.rsp.evaluation.api.CommitteeDtos.*; import com.primehr.rsp.evaluation.application.*; import com.primehr.rsp.evaluation.domain.*; import com.primehr.shared.exception.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.context.*; import org.springframework.boot.test.mock.mockito.*; import org.springframework.test.context.*; import org.springframework.transaction.annotation.*; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") @Transactional class CommitteeServiceIntegrationTest {@Autowired CommitteeService service;@MockBean CommitteeMemberEligibilityService eligibility;
 @Test void committeeRequiresEffectiveGovernanceRosterAndPreservesSuccessor(){CommitteeResponse draft=service.create("TEST-AGENCY",request("BOARD",null),"Bearer test",null);CommitteeResponse published=service.publish("TEST-AGENCY",draft.id(),new Publish(draft.recordVersion(),LocalDate.of(2026,1,1),null),"Bearer test",null);assertThat(published.status()).isEqualTo("PUBLISHED");assertThat(published.members()).extracting(MemberResponse::role).contains("CHAIRPERSON","SECRETARIAT","MEMBER");CommitteeResponse next=service.successor("TEST-AGENCY",published.id(),new Transition(published.recordVersion()),null);service.publish("TEST-AGENCY",next.id(),new Publish(next.recordVersion(),LocalDate.of(2027,1,1),null),"Bearer test",null);assertThat(service.get("TEST-AGENCY",published.id()).effectiveTo()).isEqualTo(LocalDate.of(2026,12,31));}
 @Test void duplicateEmployeeMissingRolesAndStaleVersionAreRejected(){MemberInput chair=member("001",CommitteeMember.Role.CHAIRPERSON);SaveCommittee duplicate=new SaveCommittee("DUP","Dup","EO",1,List.of(chair,chair),null);assertThatThrownBy(()->service.create("TEST-AGENCY",duplicate,"Bearer test",null)).hasMessageContaining("only once");CommitteeResponse draft=service.create("TEST-AGENCY",new SaveCommittee("NOSEC","No Secretariat","EO",1,List.of(chair,member("002",CommitteeMember.Role.MEMBER)),null),"Bearer test",null);assertThatThrownBy(()->service.publish("TEST-AGENCY",draft.id(),new Publish(draft.recordVersion(),LocalDate.of(2026,1,1),null),"Bearer test",null)).hasMessageContaining("SECRETARIAT");assertThatThrownBy(()->service.update("TEST-AGENCY",draft.id(),new SaveCommittee("NOSEC","No Secretariat","EO",1,List.of(chair),99L),"Bearer test",null)).isInstanceOf(OptimisticConflictException.class);}
 private static SaveCommittee request(String code,Long version){return new SaveCommittee(code,"HRMPSB "+code,"Agency Order",2,List.of(member("001",CommitteeMember.Role.CHAIRPERSON),member("002",CommitteeMember.Role.MEMBER),member("003",CommitteeMember.Role.SECRETARIAT)),version);}private static MemberInput member(String employee,CommitteeMember.Role role){return new MemberInput(employee,role,null,LocalDate.of(2026,1,1),null);}}
